import{_ as e,c as t,o as r,b1 as p}from"./chunks/framework.C4OOe4wF.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"nav/FaceBook/WhatsApp/帮助中心.md","filePath":"nav/FaceBook/WhatsApp/帮助中心.md","lastUpdated":1737182194000}'),s={name:"nav/FaceBook/WhatsApp/帮助中心.md"};function h(l,a,o,n,f,c){return r(),t("div",null,a[0]||(a[0]=[p('<h2 id="为什么-ss-只能同步最近-20-个联系人的对话记录" tabindex="-1"><a href="https://faq.whatsapp.com/653480766448040/?helpref=uf_share" target="_blank" rel="noreferrer">为什么 ss 只能同步最近 20 个联系人的对话记录？</a> <a class="header-anchor" href="#为什么-ss-只能同步最近-20-个联系人的对话记录" aria-label="Permalink to &quot;[为什么 ss 只能同步最近 20 个联系人的对话记录？](https://faq.whatsapp.com/653480766448040/?helpref=uf_share)&quot;">​</a></h2><p>在您关联设备后，您的主要手机会立即将最近的对话记录经端到端加密后发送到新关联的设备，并将其存储到本地。您的对话记录可能需要几分钟的时间才会显示在已连接的设备上，具体取决于对话中的消息数量。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>注意：并非所有消息和对话都会从您的手机同步到已连接的设备。WhatsApp 桌面版可同步的对话记录多于 WhatsApp 网页版。要查看或搜索您的完整对话记录，请在您手机上查看。</p></div><h2 id="关于-whatsapp-已关联的设备" tabindex="-1"><a href="https://faq.whatsapp.com/378279804439436/?helpref=uf_share" target="_blank" rel="noreferrer">关于 WhatsApp 已关联的设备</a> <a class="header-anchor" href="#关于-whatsapp-已关联的设备" aria-label="Permalink to &quot;[关于 WhatsApp 已关联的设备](https://faq.whatsapp.com/378279804439436/?helpref=uf_share)&quot;">​</a></h2><p>您最多可同时在<code>四台</code>已关联的设备上使用 WhatsApp，且无需使主要手机保持上线状态。每<code>14</code>天关联一次主要手机，让您的 WhatsApp 帐号在已关联的设备上保持登录状态。要获得最佳体验，请更新至最新版 WhatsApp。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p><a href="https://faq.whatsapp.com/378279804439436/?helpref=uf_share" target="_blank" rel="noreferrer">官方文档说明</a></p><ul><li>已关联的设备处于不活跃状态 30 天后还会自动断开连接。</li><li>如果你超过 14 天没使用手机，已关联的设备便会登出。</li></ul></div><h2 id="已关联设备的优势" tabindex="-1"><a href="https://faq.whatsapp.com/378279804439436/?helpref=uf_share" target="_blank" rel="noreferrer">已关联设备的优势</a> <a class="header-anchor" href="#已关联设备的优势" aria-label="Permalink to &quot;[已关联设备的优势](https://faq.whatsapp.com/378279804439436/?helpref=uf_share)&quot;">​</a></h2><ul><li><code>即使手机关机，也可在电脑上使用 WhatsApp。</code></li><li>可同时处理多项任务，并使用更大键盘更快速地进行输入，从而提高工作效率。</li><li>在更大屏幕上使用 WhatsApp 查看你的媒体和文件并与他人分享。</li><li>使用 Mac 版或 Windows 版 WhatsApp 应用可与最多 32 人进行语音和视频通话。</li></ul><h2 id="如何负责任地使用-whatsapp" tabindex="-1"><a href="https://faq.whatsapp.com/361005896189245/?helpref=uf_share" target="_blank" rel="noreferrer">如何负责任地使用 WhatsApp</a> <a class="header-anchor" href="#如何负责任地使用-whatsapp" aria-label="Permalink to &quot;[如何负责任地使用 WhatsApp](https://faq.whatsapp.com/361005896189245/?helpref=uf_share)&quot;">​</a></h2><p><strong>最佳实践</strong></p><ul><li><p><strong>与已知联系人联系</strong>：仅发送消息至那些已先与你联系或请求你通过 WhatsApp 与之联系的用户。最好将你的电话号码提供给联系人，以便对方先给你发消息。</p></li><li><p><strong>征求许可并尊重人与人之间的界线</strong>：你应该先获得联系人的许可，然后再将其添加到群组中。如果某位用户在你将其添加到某个群组后主动退出，请尊重其决定。</p></li><li><p><strong>使用群组控制功能</strong>：我们为 WhatsApp 群组创建了管理员专用消息设置。如果你是管理员，则可以决定是所有成员还是只有群组管理员可以在群组内发送消息。此功能有助于减少群组内不受欢迎的消息。 了解如何<a href="https://faq.whatsapp.com/526742385997912?cms_platform=android&amp;helpref=faq_content" target="_blank" rel="noreferrer">更改 WhatsApp 群组管理员设置</a>。</p></li><li><p><strong>转发消息前考虑周详</strong>：我们创建了适用于所有<a href="https://faq.whatsapp.com/1053543185312573?helpref=faq_content" target="_blank" rel="noreferrer">已转发消息</a>的标签，且对你可以转发消息的次数进行了限制，以促使用户在共享之前慎重考虑。如果你不确定某条消息是否属实，或者不知道消息的撰写者，则不建议你转发。 如需详细了解如何防止错误信息的传播，请参阅<a href="https://faq.whatsapp.com/431498999157251?helpref=faq_content" target="_blank" rel="noreferrer">这篇文章</a>。</p><p><strong>应避免的实践</strong></p></li></ul><p><code>以下述任一方式使用 WhatsApp 都可能会导致你的帐号遭封锁</code>。</p><ul><li><strong>不受欢迎的消息</strong>：如果某位联系人让你停止向其发送消息，你应将其从通讯录中移除，不再与之联系。</li><li><strong>自动发送或批量发送消息</strong>：<code>请勿使用 WhatsApp 批量发送或自动发送消息，也不要自动拨打电话</code>。WhatsApp 借助机器学习技术以及用户的举报来检测并封禁自动发送不受欢迎消息的帐号。此外，请勿以未经授权或自动方式创建帐号或群组，也请勿使用经过修改的 WhatsApp 版本。 如需详细了解 WhatsApp 如何预防自动发送和批量发送消息的滥用行为，请阅读这份<a href="https://scontent-sin11-1.xx.fbcdn.net/v/t39.8562-6/299842918_397263792546125_6219151513993243581_n.pdf?_nc_cat=107&amp;ccb=1-7&amp;_nc_sid=b8d81d&amp;_nc_ohc=lyWsR508rxYQ7kNvgGeCkmX&amp;_nc_zt=14&amp;_nc_ht=scontent-sin11-1.xx&amp;_nc_gid=AuVjVRXqpmU9bqSqmX4Wll-&amp;oh=00_AYAF_KBWfvBJ81PZIBG2QBOkAbxusEME5ehL14Rgol9zkw&amp;oe=6787BB0A" target="_blank" rel="noreferrer">白皮书</a>。</li><li><strong>使用不属于你的联系人名单</strong>：请勿在未经用户同意的情况下共享其电话号码，也请勿使用从不当来源获得的数据通过 WhatsApp 向用户发消息或将其添加到群组中。</li><li><strong>过度使用广播列表</strong>：使用广播列表发送消息时，只有在用户已将你的电话号码添加到其联系人名单时，才会收到消息。请注意，频繁使用广播消息可能会遭到用户举报，我们会封禁遭多次举报的帐号。</li><li><strong>收集个人信息</strong>：避免出于任何未经许可的目的自动从 WhatsApp 提取信息。以这种方式获取用户的信息（包括电话号码、用户的个人照片以及用户在 WhatsApp 上的动态）违反了我们的<a href="https://faq.whatsapp.com/818844662725468?helpref=faq_content" target="_blank" rel="noreferrer">服务条款</a>。</li><li><strong>违反我们的服务条款</strong>：在此提醒你，我们的服务条款禁止发布虚假信息，以及从事不法、威胁、恐吓、仇恨和在种族或民族上具有冒犯性的行为等等。 如需查看我们的服务条款，请点击<a href="https://www.whatsapp.com/legal" target="_blank" rel="noreferrer">此处</a>。</li></ul><h2 id="如何安全使用-whatsapp" tabindex="-1"><a href="https://faq.whatsapp.com/1313491802751163/?helpref=uf_share" target="_blank" rel="noreferrer">如何安全使用 WhatsApp</a> <a class="header-anchor" href="#如何安全使用-whatsapp" aria-label="Permalink to &quot;[如何安全使用 WhatsApp](https://faq.whatsapp.com/1313491802751163/?helpref=uf_share)&quot;">​</a></h2><p><strong>我们的服务条款</strong></p><p>我们帮助您在 WhatsApp 上保持安全的方法之一是通过我们的<a href="https://www.whatsapp.com/legal" target="_blank" rel="noreferrer">服务条款</a>。我们的服务条款列出了禁止进行的活动，其中包括（在动态、个人头像或消息中）分享非法、淫秽、诽谤、威胁、恐吓、骚扰、仇恨、种族攻击或者教唆或怂恿非法、不当行为或以其他方式违反我们的服务条款的内容。一旦发现某用户违反我们的服务条款，我们便会对其进行封号。</p><p>如需有关违反我们服务条款的活动的更多信息和示例，请参阅我们<a href="https://www.whatsapp.com/legal" target="_blank" rel="noreferrer">服务条款</a>中“我们的服务可接受的使用方式”(Acceptable Use of Our Services) 部分。 您还可以点击<a href="https://faq.whatsapp.com/465883178708358?helpref=faq_content" target="_blank" rel="noreferrer">此处</a>了解关于 WhatsApp 帐号被封禁的更多信息。</p><h2 id="已读回执" tabindex="-1"><strong>已读回执</strong> <a class="header-anchor" href="#已读回执" aria-label="Permalink to &quot;**已读回执**&quot;">​</a></h2><p>您还可以关闭已读回执功能。如果您关闭已读回执：</p><ul><li>您将无法收发已读回执。</li><li>即使您在隐私设置中关闭已读回执选项，群组对话的已读回执仍然始终发送。</li><li><code>当您收到非联系人发送的第一条消息时，发送者不会看到您的已读回执，直到您回复对方或将其添加为联系人为止，即使您已开启已读回执也是如此。</code></li></ul><p>如需详细了解 WhatsApp <a href="https://faq.whatsapp.com/665923838265756?helpref=faq_content" target="_blank" rel="noreferrer">已读回执功能</a>及其他隐私设置，请参阅<a href="https://faq.whatsapp.com/3307102709559968?helpref=faq_content" target="_blank" rel="noreferrer">这篇文章</a>。</p>',21)]))}const d=e(s,[["render",h]]);export{_ as __pageData,d as default};
